449	  let targetPath = (req.query.path || HOME).replace(/^~/, HOME);
450	  if (typeof targetPath !== 'string' || targetPath.includes('\0')) {
451	    return res.status(400).json({ error: 'Invalid path' });
452	  }
453	  targetPath = path.resolve(targetPath);
454	  // Restrict browsing to home directory tree
455	  if (!targetPath.startsWith(HOME)) {
456	    return res.status(403).json({ error: 'Cannot browse outside home directory' });
457	  }
458	
459	  try {
460	    if (!fs.existsSync(targetPath)) {
461	      return res.status(404).json({ error: 'Path not found' });
462	    }
463	    const stat = fs.statSync(targetPath);
464	    if (!stat.isDirectory()) {
465	      return res.status(400).json({ error: 'Not a directory' });
466	    }
467	
468	    const entries = fs.readdirSync(targetPath, { withFileTypes: true });
469	    const dirs = entries
470	      .filter(e => e.isDirectory() && !e.name.startsWith('.') && e.name !== 'node_modules' && e.name !== '__pycache__')
471	      .map(e => ({
472	        name: e.name,
473	        path: path.join(targetPath, e.name),
474	        displayPath: path.join(targetPath, e.name).replace(HOME, '~'),
475	        hasProjects: false,
476	      }))
477	      .sort((a, b) => a.name.localeCompare(b.name));
478	
479	    for (const dir of dirs) {
480	      try {
481	        const sub = fs.readdirSync(dir.path, { withFileTypes: true });
482	        dir.hasProjects = sub.some(s =>
483	          s.isDirectory() && (
484	            fs.existsSync(path.join(dir.path, s.name, '.claude')) ||
485	            fs.existsSync(path.join(dir.path, s.name, 'CLAUDE.md')) ||
486	            fs.existsSync(path.join(dir.path, s.name, 'package.json')) ||
487	            fs.existsSync(path.join(dir.path, s.name, 'pubspec.yaml'))
488	          )
489	        );
490	      } catch {}
491	    }
492	
493	    const parts = targetPath.split(path.sep).filter(Boolean);
494	    const breadcrumbs = parts.map((part, i) => ({
495	      name: i === 0 && targetPath.startsWith(HOME) ? '~' : part,
496	      path: path.sep + parts.slice(0, i + 1).join(path.sep),
497	    }));
498	
499	    if (targetPath.startsWith(HOME)) {
500	      const homeIndex = HOME.split(path.sep).filter(Boolean).length - 1;
501	      breadcrumbs.splice(0, homeIndex + 1, { name: '~', path: HOME });
502	    }
503	
504	    res.json({
505	      current: targetPath,
506	      displayPath: targetPath.replace(HOME, '~'),
507	      parent: path.dirname(targetPath) !== targetPath ? path.dirname(targetPath) : null,
508	      breadcrumbs,
509	      directories: dirs,
510	    });
511	  } catch (e) {
512	    res.status(500).json({ error: 'Cannot read directory' });
513	  }
514	});
